5860 DenseMap<Value *, SmallVector<StoreInst *>>
5861 BoUpSLP::collectUserStores(const BoUpSLP::TreeEntry *TE) const {
5862   DenseMap<Value *, SmallVector<StoreInst *>> PtrToStoresMap;
5863   for (unsigned Lane : seq<unsigned>(0, TE->Scalars.size())) {
5864     Value *V = TE->Scalars[Lane];
5865     // To save compilation time we don't visit if we have too many users.
5866     if (V->hasNUsesOrMore(UsesLimit))
5867       break;
5868 
5869     // Collect stores per pointer object.
5870     for (User *U : V->users()) {
5871       auto *SI = dyn_cast<StoreInst>(U);
5872       if (SI == nullptr || !SI->isSimple() ||
5873           !isValidElementType(SI->getValueOperand()->getType()))
5874         continue;
5875       // Skip entry if already
5876       if (getTreeEntry(U))
5877         continue;
5878 
5879       Value *Ptr = getUnderlyingObject(SI->getPointerOperand());
5880       auto &StoresVec = PtrToStoresMap[Ptr];
5881       // For now just keep one store per pointer object per lane.
5882       // TODO: Extend this to support multiple stores per pointer per lane
5883       if (StoresVec.size() > Lane)
5884         continue;
5885       // Skip if in different BBs.
5886       if (!StoresVec.empty() &&
5887           SI->getParent() != StoresVec.back()->getParent())
5888         continue;
5889       // Make sure that the stores are of the same type.
5890       if (!StoresVec.empty() &&
5891           SI->getValueOperand()->getType() !=
5892               StoresVec.back()->getValueOperand()->getType())
5893         continue;
5894       StoresVec.push_back(SI);
5895     }
5896   }
5897   return PtrToStoresMap;
