5900 bool BoUpSLP::canFormVector(ArrayRef<StoreInst *> StoresVec,
5901                             OrdersType &ReorderIndices) const {
5902   // We check whether the stores in StoreVec can form a vector by sorting them
5903   // and checking whether they are consecutive.
5904 
5905   // To avoid calling getPointersDiff() while sorting we create a vector of
5906   // pairs {store, offset from first} and sort this instead.
5907   SmallVector<std::pair<StoreInst *, int>> StoreOffsetVec(StoresVec.size());
5908   StoreInst *S0 = StoresVec[0];
5909   StoreOffsetVec[0] = {S0, 0};
5910   Type *S0Ty = S0->getValueOperand()->getType();
5911   Value *S0Ptr = S0->getPointerOperand();
5912   for (unsigned Idx : seq<unsigned>(1, StoresVec.size())) {
5913     StoreInst *SI = StoresVec[Idx];
5914     std::optional<int> Diff =
5915         getPointersDiff(S0Ty, S0Ptr, SI->getValueOperand()->getType(),
5916                         SI->getPointerOperand(), *DL, *SE,
5917                         /*StrictCheck=*/true);
5918     // We failed to compare the pointers so just abandon this StoresVec.
5919     if (!Diff)
5920       return false;
5921     StoreOffsetVec[Idx] = {StoresVec[Idx], *Diff};
5922   }
5923 
5924   // Sort the vector based on the pointers. We create a copy because we may
5925   // need the original later for calculating the reorder (shuffle) indices.
5926   stable_sort(StoreOffsetVec, [](const std::pair<StoreInst *, int> &Pair1,
5927                                  const std::pair<StoreInst *, int> &Pair2) {
5928     int Offset1 = Pair1.second;
5929     int Offset2 = Pair2.second;
5930     return Offset1 < Offset2;
5931   });
5932 
5933   // Check if the stores are consecutive by checking if their difference is 1.
5934   for (unsigned Idx : seq<unsigned>(1, StoreOffsetVec.size()))
5935     if (StoreOffsetVec[Idx].second != StoreOffsetVec[Idx - 1].second + 1)
5936       return false;
5937 
5938   // Calculate the shuffle indices according to their offset against the sorted
5939   // StoreOffsetVec.
5940   ReorderIndices.reserve(StoresVec.size());
5941   for (StoreInst *SI : StoresVec) {
5942     unsigned Idx = find_if(StoreOffsetVec,
5943                            [SI](const std::pair<StoreInst *, int> &Pair) {
5944                              return Pair.first == SI;
5945                            }) -
5946                    StoreOffsetVec.begin();
5947     ReorderIndices.push_back(Idx);
5948   }
5949   // Identity order (e.g., {0,1,2,3}) is modeled as an empty OrdersType in
5950   // reorderTopToBottom() and reorderBottomToTop(), so we are following the
5951   // same convention here.
5952   auto IsIdentityOrder = [](const OrdersType &Order) {
5953     for (unsigned Idx : seq<unsigned>(0, Order.size()))
5954       if (Idx != Order[Idx])
5955         return false;
